  drawText('DIVE SHOTS: 400 / 800 / 1600 WITH ESCORTS',20,y+14,'#888888');
  if((game.frame%60)<40) drawCentered('PRESS ENTER TO START',236,'#ffffff');
  drawCentered('ARROWS MOVE  SPACE FIRE  P PAUSE  M MUTE',260,'#666666');
}
function drawResults(){
  drawCentered('GAME OVER',60,'#ff4444',2);
  drawCentered('SHOT FIRED: '+game.shots,110,'#ffffff');
  drawCentered('HITS: '+game.hits,126,'#ffffff');
  const ratio=game.shots?Math.round(game.hits/game.shots*100):0;
  drawCentered('HIT RATIO: '+ratio+'%',142,'#ffcc22');
  drawCentered('HIGH SCORE: '+high,170,'#ffffff');
  if((game.frame%60)<40) drawCentered('PRESS ENTER',210,'#ffffff');
}

/* ---------------- Drawing: master ---------------- */
function draw(){
  ctx.fillStyle='#000'; ctx.fillRect(0,0,W,H);
  drawStars();
  const st=game.state;
  if(st==='title'){ drawTitle(); return; }
  if(st==='intro'){
    drawScene(); drawHUD();
    if(game.challenging) drawCentered('CHALLENGING STAGE',140,'#ff4444');
    else drawCentered('STAGE '+game.stage,140,'#ffffff');
    return;
  }
  if(st==='play'||st==='chalres'){
    drawScene(); drawHUD();
    if(game.player.readyT>0 && game.lives>0) drawCentered('READY',150,'#ffcc22');
    if(st==='chalres'){
      const r=game.chalRes;
      drawCentered('NUMBER OF HITS: '+r.hits,120,'#ffffff');
      if(r.bonus>0) drawCentered('WAVE BONUS: '+(r.bonus*1000),140,'#ffcc22');
      if(r.perfect) drawCentered('PERFECT! 10000',160,'#22cc44');
    }
    if(game.paused) drawCentered('PAUSE',150,'#ffffff',2);
    return;
  }
  if(st==='over'){ drawScene(); drawHUD(); drawCentered('GAME OVER',140,'#ff4444',2); return; }
  if(st==='results'){ drawResults(); }
}

/* ---------------- Fixed-timestep main loop ---------------- */
let lastT=performance.now(), acc=0;
const DT=1000/60;
function loop(now){
  requestAnimationFrame(loop);
  acc+=Math.min(now-lastT,250); lastT=now;
  while(acc>=DT){ update(); acc-=DT; }
  draw();
}
game.player={x:112,alive:true,dual:false,readyT:0,capturing:null};
requestAnimationFrame(loop);
